head.script:
scwin.trigger1_onclick = function() {
    w1.setSrc("engine_getOriginalID_WPFF-266_(WSQ-3631_)_sub1.xml");
    w2.setSrc("engine_getOriginalID_WPFF-266_(WSQ-3631_)_sub1.xml");
}
scwin.onpageload = function() {
    textbox1.setValue($p.id + "(main)");
    $p.log($p.id + "onpageload");
}
scwin.onpageunload = function() {
    $p.log($p.id + "onpageunload");
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('w1_ww1_ww1_trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('w1_ww1_ww1_trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq(WebSquare.wUnit.getDomById($p.id+'w1_ww1_ww1_textbox_test')).text() == 'textbox_test'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
